                        ?yieldNode qudt:numericValue ?yield .
                        ?ultimateNode qudt:numericValue ?ultimate .
                        ?referenceNode qudt:numericValue ?reference .
                        ?chordNode qudt:numericValue ?chord .
                        ?thicknessNode qudt:numericValue ?thickness .
                        ?rootNode qudt:numericValue ?root .
                        ?diameterNode qudt:numericValue ?diameter .
                        ?loadNode qudt:numericValue ?load .
                        BIND ((0.6 * ?yield) + (0.4 * ?ultimate) AS ?referenceExpected)
                        BIND ((300 * ?chord * ?thickness * ?thickness * ?referenceExpected) /
                              ((0.8 * ?diameter) - (2 * ?root)) AS ?loadExpected)
                        FILTER (
                            ?reference > (?referenceExpected + (0.000001 * ?referenceExpected) + 0.000001) ||
                            ?reference < (?referenceExpected - (0.000001 * ?referenceExpected) - 0.000001) ||
                            ?load > (?loadExpected + (0.000001 * ?loadExpected) + 0.000001) ||
                            ?load < (?loadExpected - (0.000001 * ?loadExpected) - 0.000001)
                        )
                    }
                ") ] ]"], "result_node": "N28f7a36185c34cd28a465a35dfd81d26", "result_paths": [], "severities": ["http://www.w3.org/ns/shacl#Violation"], "source_shapes": ["urn:nltl:generated-shape:TRF101Shape"], "values": ["https://w3id.org/nltl/benchmark/traficom-batch-h/TRF-101-F01/ship"]}, {"constraint_components": ["http://www.w3.org/ns/shacl#MinCountConstraintComponent"], "focus_nodes": ["https://w3id.org/nltl/benchmark/traficom-batch-h/TRF-101-F01/ship"], "messages": ["Less than 1 values on ex:ship->nltl:hasLoadCase"], "result_node": "N47540e8761ae4e488923233fb01c9e25", "result_paths": ["https://w3id.org/nltl/vocab#hasLoadCase"], "severities": ["http://www.w3.org/ns/shacl#Violation"], "source_shapes": ["n0fce035afd794a67ab44919096586971b10"], "values": []}, {"constraint_components": ["http://www.w3.org/ns/shacl#MinCountConstraintComponent"], "focus_nodes": ["https://w3id.org/nltl/benchmark/traficom-batch-h/TRF-101-F01/ship"], "messages": ["Less than 1 values on ex:ship->nltl:bladeFailureStatus"], "result_node": "N788799f3bbe8419e871dee91bbe68cd0", "result_paths": ["https://w3id.org/nltl/vocab#bladeFailureStatus"], "severities": ["http://www.w3.org/ns/shacl#Violation"], "source_shapes": ["n0fce035afd794a67ab44919096586971b11"], "values": []}]

