["Node ex:ship must conform to one or more shapes in [ sh:property [ sh:datatype xsd:boolean ; sh:hasValue Literal("false" = False, datatype=xsd:boolean) ; sh:message Literal("Discharge of oil or oily mixtures to sea must be recorded as false in Arctic_waters.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:oilOrOilyMixtureDischargeToSea ], [ sh:datatype xsd:string ; sh:hasValue Literal("Arctic_waters") ; sh:message Literal("The operating area must be recorded as Arctic_waters when this branch applies.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:operatingArea ] ; sh:sparql [ sh:message Literal("Oil or oily mixture discharge to sea must not have any value other than false in Arctic_waters.") ; sh:select Literal("
