PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:iceStrengtheningStatus false ;
          nltl:regulationRequiredScantling ?regulation ;
          nltl:classificationSocietyRequiredScantling ?classification .
    ?regulation qudt:numericValue ?regulationValue .
    ?classification qudt:numericValue ?classificationValue .
    FILTER (?regulationValue < ?classificationValue)
    FILTER NOT EXISTS {
        $this nltl:selectedDesignScantling ?selected .
        ?selected qudt:numericValue ?selectedValue .
        FILTER (?selectedValue = ?classificationValue)
    }
}
") ] ]"], "result_node": "N45dfe8a2b48446b7aca5b9811eab6eb2", "result_paths": [], "severities": ["http://www.w3.org/ns/shacl#Violation"], "source_shapes": ["urn:nltl:generated-shape:TRF032_Static"], "values": ["https://w3id.org/nltl/benchmark/traficom-batch-d/TRF-032-P01/ship"]}, {"constraint_components": ["http://www.w3.org/ns/shacl#MinCountConstraintComponent"], "focus_nodes": ["https://w3id.org/nltl/benchmark/traficom-batch-d/TRF-032-P01/ship"], "messages": ["Ice strengthening status is required to determine applicability of the scantling rule."], "result_node": "Nf2f4b53167d141f5a3034ed6333c5370", "result_paths": ["https://w3id.org/nltl/vocab#iceStrengtheningStatus"], "severities": ["http://www.w3.org/ns/shacl#Violation"], "source_shapes": ["nc1f72eefae894efe83fb6acc9fa3fe83b1"], "values": []}]

