["Each non-magnetic heading means must be independent from another heading means belonging to the same ship.", "Each non-magnetic heading means must identify an independent heading means.", "Value does not conform to Shape [ sh:property [ sh:class nltl:benchmarkEntity ; sh:message Literal("Each non-magnetic heading means must be connected to emergency power.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:nodeKind sh:IRI ; sh:path nltl:connectedToEmergencyPower ], [ sh:class nltl:benchmarkEntity ; sh:message Literal("Each non-magnetic heading means must be connected to main power.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:nodeKind sh:IRI ; sh:path nltl:connectedToMainPower ], [ sh:class nltl:nonMagneticHeadingMeans ; sh:message Literal("Each non-magnetic heading means must identify an independent heading means.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:nodeKind sh:IRI ; sh:path nltl:independentFromHeadingMeans ] ; sh:sparql [ sh:message Literal("Each non-magnetic heading means must be independent from another heading means belonging to the same ship.") ; sh:select Literal("
